Insertion, changing a key, and removing the minimum take `O(log n)`. `getMin`, `isEmpty`, and `heapSize` are `O(1)`. The internal array uses `O(n)` space.

This version keeps the heap in a `List<int>` and uses one repair method for both directions. After changing a key, it first tries to move the value toward the root. If that does not apply, it moves the value toward the leaves.

The code does not alter any outside array because the heap is stored internally. An invalid index is ignored, and an empty heap returns `-1` from `getMin`.

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    private readonly List<int> heap = new List<int>();

    public void initializeHeap() {
        heap.Clear();
    }

    public void insert(int key) {
        heap.Add(key);
        HeapifyUp(heap.Count - 1);
    }

    public void changeKey(int index, int new_val) {
        if (index < 0 || index >= heap.Count) {
            return;
        }

        int oldValue = heap[index];
        heap[index] = new_val;

        if (new_val < oldValue) {
            HeapifyUp(index);
        } else if (new_val > oldValue) {
            HeapifyDown(index);
        }
    }

    public void extractMin() {
        if (heap.Count == 0) {
            return;
        }

        int lastIndex = heap.Count - 1;
        heap[0] = heap[lastIndex];
        heap.RemoveAt(lastIndex);

        if (heap.Count > 0) {
            HeapifyDown(0);
        }
    }

    public bool isEmpty() {
        return heap.Count == 0;
    }

    public int getMin() {
        return heap.Count == 0 ? -1 : heap[0];
    }

    public int heapSize() {
        return heap.Count;
    }

    private void HeapifyUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (heap[parent] <= heap[index]) {
                break;
            }

            int temp = heap[parent];
            heap[parent] = heap[index];
            heap[index] = temp;
            index = parent;
        }
    }

    private void HeapifyDown(int index) {
        while (true) {
            int left = 2 * index + 1;
            int right = 2 * index + 2;
            int smallest = index;

            if (left < heap.Count && heap[left] < heap[smallest]) {
                smallest = left;
            }
            if (right < heap.Count && heap[right] < heap[smallest]) {
                smallest = right;
            }

            if (smallest == index) {
                break;
            }

            int temp = heap[index];
            heap[index] = heap[smallest];
            heap[smallest] = temp;
            index = smallest;
        }
    }
}
