class Solution {

    private lateinit var heap: MutableList<Int>

    fun initializeHeap() {
        heap = mutableListOf()
    }

    fun insert(key: Int) {
        heap.add(key)
        minHeapifyUp(heap, heap.lastIndex)
    }

    fun changeKey(index: Int, newVal: Int) {
        val oldVal = heap[index]
        heap[index] = newVal
        if (oldVal < newVal) {
            minHeapifyDown(heap, index)
        } else {
            minHeapifyUp(heap, index)
        }
    }

    fun extractMin() {
        val last = heap.removeLastOrNull() ?: return
        if (heap.isNotEmpty()) {
            heap[0] = last
            minHeapifyDown(heap, 0)
        }
    }

    fun isEmpty(): Boolean {
        return heap.isEmpty()
    }

    fun getMin(): Int {
        return heap[0]
    }

    fun heapSize(): Int {
        return heap.size
    }
}

private fun minHeapifyDown(nums: MutableList<Int>, index: Int) {
    var smallest = index
    val left = 2 * index + 1
    val right = left + 1

    if (left < nums.size && nums[smallest] > nums[left])
        smallest = left

    if (right < nums.size && nums[smallest] > nums[right])
        smallest = right

    if (smallest != index) {
        val temp = nums[index]
        nums[index] = nums[smallest]
        nums[smallest] = temp
        minHeapifyDown(nums, smallest)
    }
}

private fun minHeapifyUp(nums: MutableList<Int>, index: Int) {
    if (index == 0) return

    val parent = (index - 1)/2
    if (nums[index] < nums[parent]) {
        val temp = nums[index]
        nums[index] = nums[parent]
        nums[parent] = temp
        minHeapifyUp(nums, parent)
    }
}
