```java
class Solution {

    ArrayList<Integer> heap;
    public void initializeHeap() {
        heap = new ArrayList<>();
    }

    public void insert(int key) {
        heap.add(key);
        heapifyUp(heap.size()-1);
    }

    public void changeKey(int index, int newVal) {
        if(index < 0 || index >= heap.size()) return;
        int oldValue = heap.get(index);
        heap.set(index, newVal);
        if(newVal < oldValue){
            heapifyUp(index);
        }else{
            heapifyDown(index);
        }
    }

    public int extractMin() {
        if(isEmpty()) return -1;
        int deleted = heap.get(0);
        int last = heap.remove(heap.size()-1);

        if(!isEmpty()){
            heap.set(0, last);
            heapifyDown(0);
        }
        return deleted;
    }

    public boolean isEmpty() {
        return heap == null || heap.size() == 0;
    }

    public int getMin() {
        if(isEmpty()) return -1;
        return heap.get(0);
    }

    public int heapSize() {
        return heap == null ? 0 : heap.size();
    }

    // Helper method to maintain heap property by moving element up
    private void heapifyUp(int index) {
        while (index > 0) {
            int parentIndex = (index - 1) / 2;

            if (heap.get(index) < heap.get(parentIndex)) {
                swap(index, parentIndex);
                index = parentIndex;
            } else {
                break;
            }
        }
    }

    // Helper method to maintain heap property by moving element down
    private void heapifyDown(int index) {
        int size = heap.size();

        while (index < size) {
            int leftChild = 2 * index + 1;
            int rightChild = 2 * index + 2;
            int smallest = index;

            if (leftChild < size && heap.get(leftChild) < heap.get(smallest)) {
                smallest = leftChild;
            }

            if (rightChild < size && heap.get(rightChild) < heap.get(smallest)) {
                smallest = rightChild;
            }

            if (smallest != index) {
                swap(index, smallest);
                index = smallest;
            } else {
                break;
            }
        }
    }

    // Helper method to swap two elements
    private void swap(int i, int j) {
        int temp = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, temp);
    }

}
